"""会話の顔絵。make_portraits.py が生成する（手で編集しない）。

12〜15番はUI用の固定色。顔絵は0〜11番の12色。
"""
import base64
import zlib

import pyxel

SIZE = 80

PALETTE = (
    0xFFFFFF,
    0x000000,
    0xD67134,
    0x6483B5,
    0x4C4846,
    0xC7BBB1,
    0x923A12,
    0x987D73,
    0xEFA96D,
    0x4C1D0B,
    0x495C86,
    0x182137,
    0x0A0C14,
    0xF0F4F0,
    0x4CE896,
    0xF0B030,
)

_DATA = (
    '',
    '',
)
_CACHE = {}


def image(who):
    """話者の顔絵。初回だけ展開する。"""
    if who in _CACHE:
        return _CACHE[who]
    img = pyxel.Image(SIZE, SIZE)
    img.data_ptr()[:] = zlib.decompress(base64.b64decode(_DATA[who]))
    _CACHE[who] = img
    return img
